42	    async fn resolve_scoped_path(
43	        &self,
44	        relative_path: Option<&str>,
45	    ) -> Result<PathBuf, MemoriesBackendError> {
46	        let Some(relative_path) = relative_path else {
47	            return Ok(self.root.clone());
48	        };
49	        let relative = Path::new(relative_path);
50	        if relative.components().any(|component| {
51	            matches!(
52	                component,
53	                Component::ParentDir | Component::RootDir | Component::Prefix(_)
54	            )
55	        }) {
56	            return Err(MemoriesBackendError::invalid_path(
57	                relative_path,
58	                "must stay within the memories root",
59	            ));
60	        }
61	        if relative.components().any(is_hidden_component) {
62	            return Err(MemoriesBackendError::NotFound {
63	                path: relative_path.to_string(),
64	            });
65	        }
66	
67	        let components = relative.components().collect::<Vec<_>>();
68	        let mut scoped_path = self.root.clone();
69	        for (idx, component) in components.iter().enumerate() {
70	            scoped_path.push(component.as_os_str());
71	
72	            let Some(metadata) = Self::metadata_or_none(&scoped_path).await? else {
73	                for remaining_component in components.iter().skip(idx + 1) {
74	                    scoped_path.push(remaining_component.as_os_str());
75	                }
76	                return Ok(scoped_path);
77	            };
78	
79	            reject_symlink(&display_relative_path(&self.root, &scoped_path), &metadata)?;
80	            if idx + 1 < components.len() && !metadata.is_dir() {
81	                return Err(MemoriesBackendError::invalid_path(
82	                    relative_path,
83	                    "traverses through a non-directory path component",
84	                ));
85	            }
86	        }
87	
88	        Ok(scoped_path)
89	    }
