91	    async fn metadata_or_none(
92	        path: &Path,
93	    ) -> Result<Option<std::fs::Metadata>, MemoriesBackendError> {
94	        match tokio::fs::symlink_metadata(path).await {
95	            Ok(metadata) => Ok(Some(metadata)),
96	            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(None),
97	            Err(err) => Err(err.into()),
98	        }
