111	                MemoriesBackendError::invalid_cursor(cursor, "must be a non-negative integer")
112	            })?,
113	            None => 0,
114	        };
115	        let Some(metadata) = Self::metadata_or_none(&start).await? else {
116	            return Err(MemoriesBackendError::NotFound {
117	                path: request.path.unwrap_or_default(),
118	            });
119	        };
120	        reject_symlink(&display_relative_path(&self.root, &start), &metadata)?;
121	
122	        let mut entries = if metadata.is_file() {
123	            vec![MemoryEntry {
124	                path: display_relative_path(&self.root, &start),
125	                entry_type: MemoryEntryType::File,
126	            }]
127	        } else if metadata.is_dir() {
128	            let mut entries = Vec::new();
129	            for path in read_sorted_dir_paths(&start).await? {
