133	                let Some(metadata) = Self::metadata_or_none(&path).await? else {
134	                    continue;
135	                };
136	                if metadata.file_type().is_symlink() {
137	                    continue;
138	                }
139	
140	                let entry_type = if metadata.is_dir() {
141	                    MemoryEntryType::Directory
142	                } else if metadata.is_file() {
143	                    MemoryEntryType::File
144	                } else {
145	                    continue;
146	                };
147	                entries.push(MemoryEntry {
