168	                )
169	            }
170	            other => {
171	                return Err(McpError::invalid_params(
172	                    format!("unknown tool: {other}"),
173	                    None,
174	                ));
175	            }
176	        };
177	
178	        Ok(CallToolResult {
179	            content: vec![Content::text(structured_content.to_string())],
180	            structured_content: Some(structured_content),
181	            is_error: Some(false),
182	            meta: None,
