/// Find the tightest windows of consecutive lines (spanning at most `line_count`
/// lines) in which every query appears at least once. When a wider window
/// strictly contains a narrower valid window covering the same queries, only the
/// narrower window is reported.
fn search_file_within_lines(
    root: &Path,
    path: &Path,
    matcher: &SearchMatcher,
    context_lines: usize,
    line_count: usize,
    lines: &[&str],
    matches: &mut Vec<MemorySearchMatch>,
) {
    let line_count = line_count.max(1);
    let n = lines.len();
    let query_count = matcher.queries.len();
    let presence = lines
        .iter()
        .map(|line| matcher.query_presence(line))
        .collect::<Vec<_>>();

    // Whether every query appears somewhere in the inclusive line range [lo, hi].
    let covers_all = |lo: usize, hi: usize| -> bool {
        if lo > hi {
            return false;
        }
        (0..query_count).all(|query_idx| (lo..=hi).any(|line_idx| presence[line_idx][query_idx]))
    };

    for start in 0..n {
        let max_end = (start + line_count).saturating_sub(1).min(n.saturating_sub(1));
        // Smallest window end for this start that already covers every query.
        let Some(end) = (start..=max_end).find(|&end| covers_all(start, end)) else {
            continue;
        };
        // The window is minimal only when it cannot be shrunk from either side.
        // A smaller end is already excluded because `end` is the smallest that
        // covers all queries; check the left edge here.
        if start < end && covers_all(start + 1, end) {
            continue;
        }
        let content_start = start.saturating_sub(context_lines);
        let content_end = end
            .saturating_add(context_lines)
            .saturating_add(1)
            .min(n);
        matches.push(MemorySearchMatch {
            path: display_relative_path(root, path),
            match_line_number: start + 1,
            content_start_line_number: content_start + 1,
            content: lines[content_start..content_end].join("\n"),
            matched_queries: matcher.queries.clone(),
        });
